import React from 'react';
import { FUNDAMENTAL_SECTIONS } from '../data/fundamentalData';
import FundamentalCard from './FundamentalCard';

import PERatioCard from './PERatioCard';
import ForwardPECard from './ForwardPECard';
import PBRatioCard from './PBRatioCard';
import EarningsYieldCard from './EarningsYieldCard';

import MarketCapGDPCard from './MarketCapGDPCard';
import DividendYieldCard from './DividendYieldCard';
import EarningsTrendCard from './EarningsTrendCard';
import FIIDIIFlowCard from './FIIDIIFlowCard';

import EPSGrowthCard from './EPSGrowthCard';
import RevenueGrowthCard from './RevenueGrowthCard';
import ProfitGrowthCard from './ProfitGrowthCard';
import GDPGrowthCard from './GDPGrowthCard';

import ROECard from './ROECard';
import ROCECard from './ROCECard';
import NetMarginCard from './NetMarginCard';
import OperatingMarginCard from './OperatingMarginCard';

import DebtToEquityCard from './DebtToEquityCard';
import InterestCoverageCard from './InterestCoverageCard';
import FreeCashFlowCard from './FreeCashFlowCard';
import CurrentRatioCard from './CurrentRatioCard';

export default function FundamentalGrid({ data, selectedCategory, manualOverrides, lastUpdated }) {
  return (
    <div className="space-y-6">
      {FUNDAMENTAL_SECTIONS.map((section, idx) => {
        return (
          <div key={section.id} id={`section-${section.id}`} className="animate-in fade-in slide-in-from-bottom-4 duration-500 scroll-mt-20">
            {/* Header */}
            <div className="flex items-center justify-center gap-4 mb-3 md:mb-6">
              <div className="flex items-center gap-3">
                <span className="text-sm font-bold text-text-primary uppercase tracking-widest">{section.label}</span>
              </div>
            </div>

            {/* Card Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2.5 md:gap-4 items-start">
              {section.id === 'Valuation' && (
                <>
                  <PERatioCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                  {selectedCategory !== "Indices" && <ForwardPECard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />}
                  <PBRatioCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                  {selectedCategory !== "Indices" && <EarningsYieldCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />}
                </>
              )}
              {section.id === 'Market Health' && (
                <>
                  <MarketCapGDPCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                  <DividendYieldCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                  {selectedCategory !== "Indices" && <EarningsTrendCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />}
                  <FIIDIIFlowCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                </>
              )}
              {section.id === 'Growth' && (
                <>
                  <EPSGrowthCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                  {selectedCategory !== "Indices" && <RevenueGrowthCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />}
                  {selectedCategory !== "Indices" && <ProfitGrowthCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />}
                  <GDPGrowthCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                </>
              )}
              {section.id === 'Profitability' && selectedCategory !== "Indices" && (
                <>
                  <ROECard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                  <ROCECard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                  <NetMarginCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                  <OperatingMarginCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                </>
              )}
              {section.id === 'Financial Health' && selectedCategory !== "Indices" && (
                <>
                  <DebtToEquityCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                  <InterestCoverageCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                  <FreeCashFlowCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                  <CurrentRatioCard data={data} manualOverrides={manualOverrides} lastUpdated={lastUpdated} />
                </>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}
